324	const RETRY_FIELDS = ['attempts', 'initialDelayMs', 'backoffFactor', 'maxDelayMs'];
325	const DEFAULT_RETRY = { attempts: 1, initialDelayMs: 0, backoffFactor: 1, maxDelayMs: 0 };
326	
327	function isIntegerIn(value, min, max) {
328	  return typeof value === 'number' && Number.isInteger(value) && value >= min && value <= max;
329	}
330	
331	// A retry block is either absent (one attempt, no waiting) or present with all
332	// four parameters together, each within the same ranges the engine enforces
333	// for business action retries and compensation retries alike.
334	function compileRetry(config, label) {
335	  if (!isUsableObject(config)) {
336	    throw new Error(`${label}: retry must be an object`);
337	  }
338	  const missing = RETRY_FIELDS.filter(field => !Object.hasOwn(config, field) || config[field] === undefined);
339	  if (missing.length > 0) {
340	    throw new Error(`${label}: retry config must define all of ${RETRY_FIELDS.join(', ')} together (missing: ${missing.join(', ')})`);
341	  }
342	  if (!isIntegerIn(config.attempts, 1, 10)) {
343	    throw new Error(`${label}: retry.attempts must be an integer between 1 and 10`);
344	  }
345	  if (!isIntegerIn(config.initialDelayMs, 0, 60000)) {
346	    throw new Error(`${label}: retry.initialDelayMs must be an integer between 0 and 60000 milliseconds`);
347	  }
348	  if (!isIntegerIn(config.maxDelayMs, 0, 60000)) {
349	    throw new Error(`${label}: retry.maxDelayMs must be an integer between 0 and 60000 milliseconds`);
350	  }
351	  if (typeof config.backoffFactor !== 'number' || !Number.isFinite(config.backoffFactor)
352	    || config.backoffFactor < 1 || config.backoffFactor > 4) {
353	    throw new Error(`${label}: retry.backoffFactor must be a finite number between 1 and 4`);
354	  }
355	  if (config.maxDelayMs < config.initialDelayMs) {
356	    throw new Error(`${label}: retry.maxDelayMs must not be less than retry.initialDelayMs`);
357	  }
358	  return {
359	    attempts: config.attempts,
360	    initialDelayMs: config.initialDelayMs,
361	    backoffFactor: config.backoffFactor,
362	    maxDelayMs: config.maxDelayMs,
363	  };
364	}
365	
366	// An action node either keeps the legacy `message` behavior, names a business
367	// operation the caller supplies at run time, and/or declares a compensation
368	// operation that undoes its business effect. Both retry blocks are optional
369	// and, absent, mean exactly one attempt with no waiting.
370	function compileAction(node) {
371	  let name = null;
372	  if (Object.hasOwn(node, 'operation') && node.operation !== undefined) {
373	    if (typeof node.operation !== 'string' || node.operation.trim().length === 0) {
374	      throw new Error(`action node ${node.id}: operation must be a non-empty string name`);
375	    }
376	    name = node.operation;
377	  }
378	
379	  let retry = { ...DEFAULT_RETRY };
380	  if (Object.hasOwn(node, 'retry') && node.retry !== undefined) {
381	    if (!name) {
382	      throw new Error(`action node ${node.id}: retry config is only allowed on an action that names an operation`);
383	    }
384	    retry = compileRetry(node.retry, `action node ${node.id}`);
385	  }
386	
387	  let compensation = null;
388	  if (Object.hasOwn(node, 'compensation') && node.compensation !== undefined) {
389	    if (!isUsableObject(node.compensation)) {
390	      throw new Error(`action node ${node.id}: compensation must be an object`);
391	    }
392	    if (!name) {
393	      throw new Error(`action node ${node.id}: compensation is only allowed on an action that names an operation`);
394	    }
395	    const config = node.compensation;
396	    if (typeof config.operation !== 'string' || config.operation.trim().length === 0) {
397	      throw new Error(`action node ${node.id}: compensation.operation must be a non-empty string name`);
398	    }
399	    let compRetry = { ...DEFAULT_RETRY };
400	    if (Object.hasOwn(config, 'retry') && config.retry !== undefined) {
401	      compRetry = compileRetry(config.retry, `action node ${node.id} compensation`);
402	    }
403	    compensation = { name: config.operation, retry: compRetry };
404	  }
405	
406	  // A legacy message action (no operation) may carry a structured object or
407	  // array as its message, and the output it saves is snapshotted per run. A
408	  // value the structured clone algorithm cannot deliver — a bare function or
409	  // a function nested inside an object/array — is a definition error naming
410	  // the action and the reason, for every message action including actions on
411	  // untaken branches and entry-unreachable ones. An action that names an
412	  // operation ignores its message entirely, so an unused uncloneable message
413	  // is never rejected for it.
414	  //
415	  // A value that clones but whose clone retains shared memory is rejected for
416	  // the same reason the run input and operation return values are: cloning a
417	  // SharedArrayBuffer (or a typed array / DataView backed by one) "succeeds"
418	  // while the clone keeps sharing the underlying bytes, so the independent
419	  // output copy the action promises — including against the definition's own
420	  // message, which the engine clones again at execution time — could not be
421	  // guaranteed. The check therefore runs on the cloned value with the same
422	  // clone-shaped traversal (containsSharedMemory): shared memory placed only
423	  // where cloning drops it (an attached property of a Date/RegExp, a
424	  // non-enumerable property, an Error own property other than cause) is
425	  // discarded with that property and never condemns the message.
426	  //
427	  // Validation only proves the message was safe as it was then; the same two
428	  // checks are re-enforced at the action's own execution moment by
429	  // captureActionMessage below, exactly as for end-node results.
430	  if (name === null && Object.hasOwn(node, 'message') && node.message !== undefined) {
431	    let cloned;
432	    try {
433	      cloned = structuredClone(node.message);
434	    } catch {
435	      throw new Error(ACTION_MESSAGE_UNCLONEABLE_MESSAGE(node.id));
436	    }
437	    if (containsSharedMemory(cloned)) {
438	      throw new Error(ACTION_MESSAGE_SHARED_MEMORY_MESSAGE(node.id));
439	    }
440	  }
441	
442	  return { name, retry, compensation };
443	}
444	
445	// The two failure kinds a legacy message can produce, shared by definition
446	// validation (compileAction above) and the execution-time capture
447	// (captureActionMessage below): the message cannot be structured-cloned at
448	// all, or it clones but the clone retains shared memory. Uncloneability takes
449	// precedence when a message carries both, at both moments.
450	const ACTION_MESSAGE_UNCLONEABLE_MESSAGE = nodeId =>
451	  `action node ${nodeId}: message must be a structured-cloneable value (objects and arrays must not contain functions)`;
452	const ACTION_MESSAGE_SHARED_MEMORY_MESSAGE = nodeId =>
453	  `action node ${nodeId}: message contains shared memory (SharedArrayBuffer or a typed array/DataView backed by one); independent copies cannot be guaranteed, so shared bytes must not enter the action output`;
454	
455	// Reads a legacy message action's configured message at the action's own
456	// execution moment and produces the independent copy that will be saved as
457	// the node's output. This re-enforces, for exactly the content this run is
458	// about to save, the promise validation already made for the message as it
459	// was then: an enumerable getter can return ordinary data during validation
460	// and shared memory (or a function) when the action later runs, and a
461	// preceding business operation — or work on another activated branch — can
462	// replace a message's plain buffer with a shared one before this action
463	// executes.
464	//
465	//   - the root message is read exactly once here, and every nested enumerable
466	//     accessor is read only by structuredClone's own read — there is no
467	//     separate inspection pass over the original, so a getter's return order
468	//     is never disturbed, and the value this read produced is both what is
469	//     judged and what is saved (a legal message whose getter answers with a
470	//     different ordinary value at execution time saves that fresh value);
471	//   - shared memory the clone retains is rejected (containsSharedMemory runs
472	//     on the clone), while shared memory placed only where cloning drops it
473	//     is discarded with that property and never condemns the message;
474	//   - uncloneability takes precedence over shared memory, matching
475	//     validation: the clone is attempted first and its failure short-circuits
476	//     before the shared-memory traversal. A root getter that throws, a nested
477	//     getter that throws while the clone reads it, and a value that cannot be
478	//     cloned at all (a function) all surface as the same uncloneable error.
479	//
480	// An unset, undefined or null message still defaults to action:<node id>,
481	// while "", 0 and false pass through untouched.
482	//
483	// Any failure is thrown here as an ordinary Error naming the action node
484	// rather than recorded as a run status: the synchronous entry propagates it
485	// and the asynchronous entry's rejected Promise carries it. It is never an
486	// action_failed — a legacy message action has no retry budget — and it
487	// neither consumes business-action retries nor triggers compensation, and no
488	// success output is recorded for the node.
489	function captureActionMessage(node) {
490	  let message;
491	  try {
492	    // The root value's single read: an absent, undefined or null message
493	    // takes the default; a root getter that throws is the uncloneable error.
494	    message = node.message;
495	  } catch {
496	    throw new Error(ACTION_MESSAGE_UNCLONEABLE_MESSAGE(node.id));
497	  }
498	  if (message === undefined || message === null) return `action:${node.id}`;
499	  let cloned;
500	  try {
501	    cloned = structuredClone(message);
502	  } catch {
503	    throw new Error(ACTION_MESSAGE_UNCLONEABLE_MESSAGE(node.id));
504	  }
505	  if (containsSharedMemory(cloned)) {
506	    throw new Error(ACTION_MESSAGE_SHARED_MEMORY_MESSAGE(node.id));
507	  }
508	  return cloned;
509	}
510	
511	// An end node's result is delivered to the caller verbatim for primitives
512	// (null, undefined, strings, numbers, booleans), but an object or array result
513	// must be structured-clonable. The independent-copy promise is enforced at
514	// BOTH moments it can be observed:
