1580	    state.activated.add(outcome.value ? node.then : node.else);
1581	  } else {
1582	    for (const target of successorTargets.get(node)) state.activated.add(target);
1583	  }
1584	  state.completed.add(node.id);
1585	  return null;
1586	}
1587	
1588	// Verifies, before a single node can run, that every business operation and
1589	// every compensation operation in the definition has a function registered —
1590	// including actions on untaken branches and entry-unreachable nodes.
1591	function resolveImplementation(operations, name, nodeId, kind) {
1592	  if (!isUsableObject(operations)
1593	    || !Object.hasOwn(operations, name)
1594	    || typeof operations[name] !== 'function') {
1595	    throw new Error(`action node ${nodeId}: ${kind} operation "${name}" has no function implementation; pass it to executeWorkflowAsync`);
1596	  }
1597	  return operations[name];
1598	}
1599	
1600	function verifyOperations(nodes, operations) {
1601	  for (const node of nodes.values()) {
1602	    const binding = actionBindings.get(node);
1603	    if (binding && binding.name !== null) {
1604	      resolveImplementation(operations, binding.name, node.id, 'business');
1605	    }
1606	    if (binding && binding.compensation !== null) {
1607	      resolveImplementation(operations, binding.compensation.name, node.id, 'compensation');
1608	    }
1609	  }
1610	}
1611	
1612	// The optional fourth argument of executeWorkflowAsync carries an
1613	// AbortSignal as `{ signal }`. Omitting it — or passing undefined, or an
1614	// options object without a signal — keeps the previous behavior; anything
1615	// else is a caller error reported before a single node executes.
1616	function resolveRunSignal(options) {
1617	  if (options === undefined) return null;
1618	  if (!isUsableObject(options)) {
1619	    throw new TypeError('executeWorkflowAsync options must be an object with an optional "signal" AbortSignal');
1620	  }
1621	  if (!Object.hasOwn(options, 'signal') || options.signal === undefined) return null;
1622	  const { signal } = options;
1623	  if (signal instanceof AbortSignal) return signal;
1624	  throw new TypeError('executeWorkflowAsync options.signal must be an AbortSignal');
1625	}
1626	
1627	export function executeWorkflow(workflow, input = {}) {
1628	  const nodes = validateWorkflow(workflow);
1629	  // Business operations are asynchronous: the synchronous entry must refuse
1630	  // a workflow that names any before a single node executes.
1631	  for (const node of nodes.values()) {
1632	    const binding = actionBindings.get(node);
1633	    if (binding && binding.name !== null) {
1634	      throw new Error(`action node ${node.id} names business operation "${binding.name}", which must run asynchronously; use executeWorkflowAsync instead of executeWorkflow`);
1635	    }
1636	  }
1637	
1638	  const state = createRunState(nodes, workflow, input);
1639	
1640	  for (;;) {
1641	    const step = advanceSchedule(state);
1642	
1643	    if (step.kind === 'blocked') {
1644	      return { status: 'blocked', context: state.context, trace: state.trace, blockedNodes: step.waiting };
1645	    }
1646	    if (step.kind === 'completed') {
1647	      return { status: 'completed', result: state.endResult, context: state.context, trace: state.trace };
1648	    }
1649	    if (step.kind === 'end') continue;
1650	
1651	    const early = applyRegularNode(step.node, state);
1652	    if (early) return early;
1653	  }
1654	}
1655	
1656	// Attaches compensation results to a failed run. Successful outputs and the
1657	// original terminal status stay untouched; compensation records live on
1658	// their own fields, never in the regular node trace.
1659	async function withCompensation(result, state, operations) {
1660	  const outcome = await compensateRun(state, operations);
1661	  result.compensationStatus = outcome.attempts.length === 0 ? 'not_needed' : outcome.status;
1662	  result.compensationAttempts = outcome.attempts;
1663	  return result;
1664	}
1665	
1666	// The cancelled terminal shape: the run stops where it is, keeps the
1667	// context, trace and attempt records produced so far, and never carries a
1668	// success result. Compensation for already-succeeded actions is attached by
1669	// withCompensation under the usual rules.
1670	function cancelledResult(state) {
1671	  return {
1672	    status: 'cancelled',
1673	    context: state.context,
1674	    trace: state.trace,
1675	    actionAttempts: state.actionAttempts,
1676	  };
1677	}
1678	
1679	export async function executeWorkflowAsync(workflow, input = {}, operations = {}, options = undefined) {
1680	  const signal = resolveRunSignal(options);
1681	  const nodes = validateWorkflow(workflow);
1682	  verifyOperations(nodes, operations);
1683	
1684	  const state = createRunState(nodes, workflow, input);
1685	
1686	  // A signal that is already aborted stops the run before the first node —
1687	  // but only after the definition and the operation registrations above have
1688	  // been checked. Nothing executes and nothing is compensated.
1689	  if (signal && signal.aborted) {
1690	    return withCompensation(cancelledResult(state), state, operations);
1691	  }
1692	
1693	  for (;;) {
1694	    // Once the signal fires, no new regular node runs and no new business
1695	    // action attempt starts; the run ends cancelled with whatever state it
1696	    // reached, even if an end node was already visited on another branch.
1697	    if (signal && signal.aborted) {
1698	      return withCompensation(cancelledResult(state), state, operations);
1699	    }
1700	
1701	    const step = advanceSchedule(state);
1702	
1703	    if (step.kind === 'blocked') {
1704	      // Unmet dependencies end the run; successful compensable actions are
1705	      // rolled back even though an end node may already have been reached.
1706	      return withCompensation({
1707	        status: 'blocked', context: state.context, trace: state.trace,
1708	        blockedNodes: step.waiting, actionAttempts: state.actionAttempts,
1709	      }, state, operations);
1710	    }
1711	    if (step.kind === 'completed') {
1712	      // A completed run never invokes compensation.
1713	      return {
1714	        status: 'completed', result: state.endResult, context: state.context,
1715	        trace: state.trace, actionAttempts: state.actionAttempts,
1716	        compensationStatus: 'not_needed', compensationAttempts: [],
1717	      };
1718	    }
1719	    if (step.kind === 'end') continue;
1720	
1721	    const ready = step.node;
1722	    if (ready.type === 'action') {
1723	      const binding = actionBindings.get(ready);
1724	      if (binding.name !== null) {
1725	        // Nodes execute one at a time in declaration order; awaiting here
1726	        // never lets another node jump ahead.
1727	        const actionResult = await runBusinessAction(
1728	          ready, binding, operations[binding.name], state.context, state.actionAttempts, signal);
1729	        if (!actionResult.ok) {
1730	          if (actionResult.cancelled) {
1731	            // Cancelled while the action was in flight or waiting to retry:
1732	            // the attempt records produced so far stay as they are.
1733	            return withCompensation(cancelledResult(state), state, operations);
1734	          }
1735	          // Retries are exhausted: stop immediately with prior input/output
1736	          // preserved, no output for this node and no successors activated —
1737	          // even if an end node was already reached — then compensate every
1738	          // earlier successful action that asked for it.
1739	          return withCompensation({
1740	            status: 'action_failed', nodeId: ready.id, attempts: binding.retry.attempts,
1741	            error: actionResult.error, context: state.context, trace: state.trace,
1742	            actionAttempts: state.actionAttempts,
1743	          }, state, operations);
1744	        }
