1766	    const early = applyRegularNode(ready, state);
1767	    if (early) {
1768	      early.actionAttempts = state.actionAttempts;
1769	      // A failed form (invalid_input) or failed condition evaluation
1770	      // (invalid_condition) ends normal execution and triggers compensation
1771	      // of the successful business actions that ran earlier.
1772	      return withCompensation(early, state, operations);
1773	    }
