import { executeWorkflow, executeWorkflowAsync, validateWorkflow } from "./src/engine.js";

const wf = (node) => ({ id: "w", entry: "s", nodes: [
  { id: "s", type: "trigger", next: "e" },
  node,
]});
const endNode = (extra) => ({ id: "e", type: "end", ...extra });
const actNode = (extra) => ({ id: "e", type: "action", ...extra });

// 1. Root result getter throws at execution -> end-node uncloneable Error
{
  const node = endNode({});
  Object.defineProperty(node, "result", { get() { throw new Error("x"); }, enumerable: true, configurable: true });
  try { executeWorkflow(wf(node), {}); console.log("FAIL 1: no throw"); }
  catch (e) { console.log("1:", /end node e: result must be a structured-cloneable value/.test(e.message) ? "OK" : "FAIL: "+e.message); }
}

// 2. Root message getter throws at execution -> action error
{
  const node = actNode({});
  Object.defineProperty(node, "message", { get() { throw new Error("x"); }, enumerable: true, configurable: true });
  const w = wf(node);
  try { executeWorkflow(w, {}); console.log("FAIL 2: no throw"); }
  catch (e) { console.log("2:", /action node e: message must be a structured-cloneable value/.test(e.message) ? "OK" : "FAIL: "+e.message); }
}

// 3. Message property deleted after validation -> action:<id> default
{
  const node = actNode({ message: "hello" });
  const w = { id: "w", entry: "s", nodes: [
    { id: "s", type: "trigger", next: "e" },
    node,
    { id: "z", type: "end", result: "z" },
  ]};
  node.next = "z";
  validateWorkflow(w);
  delete node.message;
  const r = executeWorkflow(w, {});
  console.log("3:", r.context.output.e === "action:e" ? "OK" : "FAIL: "+r.context.output.e);
}

// 4. Result changed to undefined after validation -> null
{
  const node = { id: "e", type: "end", result: "hello" };
  const w = wf(node);
  validateWorkflow(w);
  node.result = undefined;
  const r = executeWorkflow(w, {});
  console.log("4:", r.result === null ? "OK" : "FAIL: "+r.result);
}

// 5. Read-once: nested getter read counts
{
  let reads = 0;
  const obj = { get flip() { reads++; return reads === 1 ? "v" : new SharedArrayBuffer(4); } };
  const node = endNode({ result: obj });
  const w = wf(node);
  validateWorkflow(w); // read 1
  try { executeWorkflow(w, {}); } catch {}
  console.log("5:", reads === 2 ? "OK" : "FAIL reads="+reads);
}

// 6. Uncloneable precedence at execution
{
  let reads = 0;
  const obj = { get flip() { reads++; return reads === 1 ? "v" : { fn: () => 1, s: new SharedArrayBuffer(4) }; } };
  const node = endNode({ result: obj });
